window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-b8b0ca244cacb1be"]={"versions": [{"id": "FIG-b8b0ca244cacb1be", "releases": ["R3.0.7", "R3.1.5"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> UML-Klassendiagramm / Metamodell-Ausschnitt (M2-Ebene) aus dem <em>AUTOSAR Generic Structure Template</em> (Release R3.0.7 / R3.1.5).\n</li><li><strong>Technischer Zweck:</strong> Definition des standardisierten Basistyps zur Spezifikation der Byte-Reihenfolge (Endianness) von Verarbeitungseinheiten (Processing Units/Hardware-Cores), Datentypen und Übertragungsstrukturen im Metamodell.\n</li><li><strong>Funktionale Einordnung:</strong> Dient Generatoren und Toolchains als semantische Referenz zur formalen Modellierung der Speicherorganisation von Hardware-Plattformen sowie zur Definition von Signal- und PDU-Serialisierungen im Kommunikations- und Basishardware-Metamodell.\n</li></ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong><code>«enumeration» ByteOrderEnum</code></strong>:\n<ul class=\"fig-list\"><li>Aufzählungstyp für die Definition der Speicheranordnung mehrgliedriger Datenworte.\n</li><li><strong>Literale:</strong>\n<ul class=\"fig-list\"><li><code>mostSignificantByteFirst</code>: Big-Endian-Format (Motorola-Notation; das höchstwertige Byte belegt die niedrigste Speicheradresse bzw. wird im Datenstrom zuerst übertragen).\n</li><li><code>mostSignificantByteLast</code>: Little-Endian-Format (Intel-Notation; das niederwertigste Byte belegt die niedrigste Speicheradresse bzw. wird im Datenstrom zuerst übertragen).\n</li></ul>\n</li></ul>\n</li><li><strong><code>ByteOrder::ByteOrder</code></strong>:\n<ul class=\"fig-list\"><li>Qualifizierte Metamodell-Klasse (Package <code>ByteOrder</code>, Klasse <code>ByteOrder</code>) zur XML-/ARXML-konformen Repräsentation des Endianness-Attributs im MSR-basierten Schema.\n</li><li><strong>Attribute:</strong>\n<ul class=\"fig-list\"><li><code>+ content: ByteOrderEnum [1]</code>: Obligatorischer Nutzdatenwert (Element-Content), der die konkrete Endianness abbildet.\n</li><li><code>+ type: ByteOrderEnum [0..1]</code>: Optionales XML-Typattribut (<code>[0..1]</code>) zur schema-technischen Qualifizierung des Enumerationstyps.\n</li></ul>\n</li></ul>\n</li></ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf (falls zutreffend)</h4>\n<ul class=\"fig-list\"><li><strong>Statisches Metamodell:</strong> Es liegt kein direktes Laufzeitverhalten (keine Zustandswechsel oder Sequenzen) vor.\n</li><li><strong>Generierungszeit-Semantik:</strong> \n<ul class=\"fig-list\"><li>Validierungsschritt während der Codegenerierung (COM, PDU Router, RTE, OS).\n</li><li>Ein Wertevergleich zwischen der <code>ByteOrder</code> der Ziel-CPU (<code>ProcessingUnit</code>) und der <code>ByteOrder</code> der Netzwerk-Signale/PDUs steuert die Injektion von Konvertierungsroutinen (Byte-Swapping via ASM-Befehle wie <code>REV</code>/Makros) beim Packen und Entpacken von Datenströmen.\n</li></ul>\n</li></ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Treiber- &amp; Stack-Entwicklung (COM / CanIf / PduR):</strong>\n<ul class=\"fig-list\"><li>Definiert die Basis für das Signal-Unpacking/-Packing. Stimmt die <code>ByteOrder</code> der Zielhardware (z. B. Little-Endian bei ARM Cortex-M/R, TriCore) nicht mit der konfigurierten Signal-Endianness überein, muss der COM-Stack Swapping-Operationen ausführen.\n</li><li>Falsch konfigurierte Werte führen zu fehlerhafter Interpretation mehrbytiger Payload-Daten (z. B. <code>uint16</code>, <code>uint32</code>, Float) auf dem CAN-/LIN-/FlexRay-Bus ohne Compile-Zeit-Fehler.\n</li></ul>\n</li><li><strong>MCAL &amp; Hardware-Abstraktion:</strong>\n<ul class=\"fig-list\"><li>Verbindliche Kennzeichnung der Hardware-Architektur im System-Description-File (<code>HwElement</code> / <code>ProcessingUnit</code>).\n</li></ul>\n</li><li><strong>ARXML-Kompatibilität:</strong>\n<ul class=\"fig-list\"><li>R3.x-Metamodell-Definition: Die direkte Trennung von <code>content</code> und <code>type</code> spiegelt das frühe MSR-SW-XML-Binding wider. In späteren AUTOSAR-Releases (ab 4.x) wurde die Modellierung harmonisiert (z. B. <code>ByteOrderEnum</code> mit Werten wie <code>MOST-SIGNIFICANT-BYTE-FIRST</code> bzw. <code>MOST-SIGNIFICANT-BYTE-LAST</code> direkt an <code>BaseType</code> und <code>NetworkRepresentationProps</code>).\n</li></ul>\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-645524229c7d41f1", "releases": ["R3.2.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> UML-Klassendiagramm / Metamodell-Ausschnitt (M2-Ebene) aus dem <em>AUTOSAR Generic Structure Template</em> (Release R3.0.7 / R3.1.5).\n</li><li><strong>Technischer Zweck:</strong> Definition des standardisierten Basistyps zur Spezifikation der Byte-Reihenfolge (Endianness) von Verarbeitungseinheiten (Processing Units/Hardware-Cores), Datentypen und Übertragungsstrukturen im Metamodell.\n</li><li><strong>Funktionale Einordnung:</strong> Dient Generatoren und Toolchains als semantische Referenz zur formalen Modellierung der Speicherorganisation von Hardware-Plattformen sowie zur Definition von Signal- und PDU-Serialisierungen im Kommunikations- und Basishardware-Metamodell.\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong><code>«enumeration» ByteOrderEnum</code></strong>:\n<ul class=\"fig-list\"><li>Aufzählungstyp für die Definition der Speicheranordnung mehrgliedriger Datenworte.\n</li><li><strong>Literale:</strong>\n<ul class=\"fig-list\"><li><code>mostSignificantByteFirst</code>: Big-Endian-Format (Motorola-Notation; das höchstwertige Byte belegt die niedrigste Speicheradresse bzw. wird im Datenstrom zuerst übertragen).\n</li><li><code>mostSignificantByteLast</code>: Little-Endian-Format (Intel-Notation; das niederwertigste Byte belegt die niedrigste Speicheradresse bzw. wird im Datenstrom zuerst übertragen).\n</li></ul>\n</li></ul>\n</li><li><strong><code>ByteOrder::ByteOrder</code></strong>:\n<ul class=\"fig-list\"><li>Qualifizierte Metamodell-Klasse (Package <code>ByteOrder</code>, Klasse <code>ByteOrder</code>) zur XML-/ARXML-konformen Repräsentation des Endianness-Attributs im MSR-basierten Schema.\n</li><li><strong>Attribute:</strong>\n<ul class=\"fig-list\"><li><code>+ content: ByteOrderEnum [1]</code>: Obligatorischer Nutzdatenwert (Element-Content), der die konkrete Endianness abbildet.\n</li><li><code>+ type: ByteOrderEnum [0..1]</code>: Optionales XML-Typattribut (<code>[0..1]</code>) zur schema-technischen Qualifizierung des Enumerationstyps.\n</li></ul>\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\"><li><strong>Statisches Metamodell:</strong> Es liegt kein direktes Laufzeitverhalten (keine Zustandswechsel oder Sequenzen) vor.\n</li><li><strong>Generierungszeit-Semantik:</strong> \n<ul class=\"fig-list\"><li>Validierungsschritt während der Codegenerierung (COM, PDU Router, RTE, OS).\n</li><li>Ein Wertevergleich zwischen der <code>ByteOrder</code> der Ziel-CPU (<code>ProcessingUnit</code>) und der <code>ByteOrder</code> der Netzwerk-Signale/PDUs steuert die Injektion von Konvertierungsroutinen (Byte-Swapping via ASM-Befehle wie <code>REV</code>/Makros) beim Packen und Entpacken von Datenströmen.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Treiber- &amp; Stack-Entwicklung (COM / CanIf / PduR):</strong>\n<ul class=\"fig-list\"><li>Definiert die Basis für das Signal-Unpacking/-Packing. Stimmt die <code>ByteOrder</code> der Zielhardware (z. B. Little-Endian bei ARM Cortex-M/R, TriCore) nicht mit der konfigurierten Signal-Endianness überein, muss der COM-Stack Swapping-Operationen ausführen.\n</li><li>Falsch konfigurierte Werte führen zu fehlerhafter Interpretation mehrbytiger Payload-Daten (z. B. <code>uint16</code>, <code>uint32</code>, Float) auf dem CAN-/LIN-/FlexRay-Bus ohne Compile-Zeit-Fehler.\n</li></ul>\n</li><li><strong>MCAL &amp; Hardware-Abstraktion:</strong>\n<ul class=\"fig-list\"><li>Verbindliche Kennzeichnung der Hardware-Architektur im System-Description-File (<code>HwElement</code> / <code>ProcessingUnit</code>).\n</li></ul>\n</li><li><strong>ARXML-Kompatibilität:</strong>\n<ul class=\"fig-list\"><li>R3.x-Metamodell-Definition: Die direkte Trennung von <code>content</code> und <code>type</code> spiegelt das frühe MSR-SW-XML-Binding wider. In späteren AUTOSAR-Releases (ab 4.x) wurde die Modellierung harmonisiert (z. B. <code>ByteOrderEnum</code> mit Werten wie <code>MOST-SIGNIFICANT-BYTE-FIRST</code> bzw. <code>MOST-SIGNIFICANT-BYTE-LAST</code> direkt an <code>BaseType</code> und <code>NetworkRepresentationProps</code>).\n</li></ul>\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-b8b0ca244cacb1be", "to": "FIG-645524229c7d41f1", "fr": "R3.1.5", "tr": "R3.2.3", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
